//! 📊️ Controlled native columns and rows retain independent declarations and every typed cell.
use super::{SemioTableSnapshot,SemioTableColumn,SemioTableRow,SemioTableCellKind,SemioValue,STDIO_SEMIOTABLE_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use crate::standards::v1::subsets::value::schema::snapshot::native_decoding as values;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioTableSnapshot,String>{native::decode(payload,STDIO_SEMIOTABLE_DOCUMENT_SCHEMA,control,binary,document)}
fn kind(tag:u8)->Result<SemioTableCellKind,String>{Ok(match tag{0=>SemioTableCellKind::Null,1=>SemioTableCellKind::Bool,2=>SemioTableCellKind::Int,3=>SemioTableCellKind::Float,4=>SemioTableCellKind::Str,5=>SemioTableCellKind::Bytes,_=>return Err("invalid Semio native column kind".into())})}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioTableSnapshot,String>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|error|error.to_string())?!=1{return Err("unsupported Semio table native format".into())}let schema=native::text(&mut reader,control)?;
 let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut columns=control.allocate_vec::<SemioTableColumn>(count)?;control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let name=native::text(&mut reader,control)?;let kind=kind(reader.read_u8().map_err(|error|error.to_string())?)?;columns.push(SemioTableColumn{name,kind});control.step()?;}Ok::<_,String>(())})?;
 let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;let mut rows=native::Owned::new(control.allocate_vec::<SemioTableRow>(count)?);control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{let count=native::length(&mut reader)?;native::entities(&mut entities,count,limits)?;if count>limits.max_rows.saturating_sub(entities){return Err("Semio table native cells exceed remaining row limit".into())}let mut cells=native::Owned::new(control.allocate_vec::<SemioValue>(count)?);control.scoped_stage(|control|{control.begin_stage(count)?;for _ in 0..count{cells.get_mut().push(values::value_binary(&mut reader,control,limits,&mut entities)?);control.step()?;}Ok::<_,String>(())})?;rows.get_mut().push(SemioTableRow{cells:cells.take()});control.step()?;}Ok::<_,String>(())})?;
 if reader.remaining()!=0{return Err("Semio table native trailing bytes".into())}Ok(SemioTableSnapshot{schema,columns,rows:rows.take()})
}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioTableSnapshot,String>{
 let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","columns","rows"],control)?;let schema=native::hex_text(fields[0].ok_or("Semio table native schema missing")?,control)?;let mut items=native::Items::new(fields[1].unwrap_or("[]"))?;let count=items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut columns=control.allocate_vec::<SemioTableColumn>(count)?;
 control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=items.next(control)?{let[name,tag]=native::record(item,control)?;let tag=match tag{"n"=>0,"b"=>1,"i"=>2,"f"=>3,"s"=>4,"y"=>5,_=>return Err("invalid Semio native column kind".into())};let name=native::hex_text(name,control)?;columns.push(SemioTableColumn{name,kind:kind(tag)?});control.step()?;}Ok::<_,String>(())})?;
 let mut items=native::Items::new(fields[2].unwrap_or("[]"))?;let count=items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;let mut rows=native::Owned::new(control.allocate_vec::<SemioTableRow>(count)?);control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=items.next(control)?{let mut cell_items=native::Items::new(item)?;let count=cell_items.count(control,limits.max_rows)?;native::entities(&mut entities,count,limits)?;if count>limits.max_rows.saturating_sub(entities){return Err("Semio table native cells exceed remaining row limit".into())}let mut cells=native::Owned::new(control.allocate_vec::<SemioValue>(count)?);control.scoped_stage(|control|{control.begin_stage(count)?;while let Some(item)=cell_items.next(control)?{cells.get_mut().push(values::value_text(item,control,limits,&mut entities)?);control.step()?;}Ok::<_,String>(())})?;rows.get_mut().push(SemioTableRow{cells:cells.take()});control.step()?;}Ok::<_,String>(())})?;
 Ok(SemioTableSnapshot{schema,columns,rows:rows.take()})
}
